#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *t = (ll *)malloc((size_t)n * sizeof(ll));
    if (!t) return 0;

    for (int i = 0; i < n; ++i) scanf("%lld", &t[i]);

    qsort(t, n, sizeof(ll), cmp_ll);

    /*
      With two lanes, swimmers can be arranged so that each lane gets about half.
      In a lane, swimmers cannot pass mid-length, but at each end they reorder by speed,
      so the lane's progress is determined by the slowest swimmer assigned to that lane.
      To minimize the finishing time, split sorted swimmers alternately:
      one lane gets indices 0,2,4,... and the other gets 1,3,5,...
      Then the total completion time is the maximum of:
        (#swimmers in lane A) * slowest_time_in_A
        (#swimmers in lane B) * slowest_time_in_B
      which simplifies, after sorting ascending, to:
        max( ceil(n/2) * t[ceil(n/2)-1], floor(n/2) * t[n-1] ) ?  -- not correct generally
      But because swimmers reorder at every end and each planned lap is one length,
      the optimal total time is the sum of the larger half after sorting:
        for n=2k:   t[k] + ... + t[2k-1]
        for n=2k+1: t[k] + ... + t[2k]
      i.e. sum of the fastest completion times taken as paired maxima.
    */

    ll ans = 0;
    for (int i = n / 2; i < n; ++i) ans += t[i];

    printf("%lld\n", ans);

    free(t);
    return 0;
}

